update public.venues v
set public_visible=false,
    review_reason=concat_ws(E'\n', nullif(v.review_reason,''), d.reason),
    ops_reviewed_at=now()
from decisions d
where v.source_url=d.source_url and v.venue_name is not distinct from d.expected_name
  and v.category='Amusement arcade' and v.public_visible=true;

-- Parks are stored mainly as Children’s playground. Do not include customers,
-- permissive, yes, restricted or unknown access in this explicitly private scope.
update public.venues
set public_visible=false,
    review_reason=concat_ws(E'\n', nullif(review_reason,''), '2026-10-14 owner decision: hide private park/playground. Imported access=private; evidence: ' || coalesce(source_url,'source unavailable')),
    ops_reviewed_at=now()
where lower(trim(access))='private' and public_visible=true
  and (category ilike '%playground%' or category ilike '%park%');
commit;
